@startuml

class HospitalHouseMD {}

abstract class Patient {}
abstract class Doctor {}
abstract class Treatment {}
abstract class Diagnosis {}
abstract class ConsentForm {}

enum PriorityScore {
  High
  Low
}

enum TreatmentStage {
  Stage1
  Stage2
  Stage3
}

class Illness {
  + priorityScore : PriorityScore
}

class TreatmentPlan {}

class AdvisedExamination {}

class Permission {}

class Consultation {}

class FreeExamination {}

Patient "1" -- "*" Doctor
Doctor "1" -- "*" Diagnosis
Diagnosis "1" -- "*" Treatment
Treatment "1" -- "0..*" AdvisedExamination
AdvisedExamination "0..*" -- "1" Permission
FreeExamination "0..*" -- "1" Permission
Consultation "0..*" -- "1" Affiliation
Consultation "0..*" -- "1" Patient
Affiliation "0..*" -- "1" Doctor
Affiliation "0..*" -- "1" HospitalHouseMD
Permission "0..*" -- "1" HospitalHouseMD
TreatmentPlan "1" -- "0..*" AdvisedExaminationType
AdvisedExaminationType "0..*" -- "1" ExaminationType

HospitalHouseMD "1" -- "*" Illness
Illness "1" -- "*" TreatmentPlan
Treatment "1" -- "0..1" ConsentForm
ConsentForm "1" -- "0..1" Patient
Patient "1" -- "0..1" PriorityScore

@enduml

